/**
 * SVG de un ícono. $style: brands | regular | solid.
 */
function webokids_icon( $name, $style = 'solid' ) {
  $icons = webokids_icons();
  $key   = $style . '/' . $name;
  if ( ! isset( $icons[ $key ] ) ) {
    return '';
  }
  list( $viewbox, $path ) = $icons[ $key ];
  return '<svg class="svg-inline--fa fa-' . esc_attr( $name ) . '" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" viewBox="' . esc_attr( $viewbox ) . '"><path fill="currentColor" d="' . esc_attr( $path ) . '"/></svg>';
}

/**
 * Cambia los <i class="fa-{style} fa-{name}"></i> de un HTML por su SVG inline.
 * Los íconos que no estén en webokids_icons() se dejan como están.
 */
function webokids_replace_fa_icons( $html ) {
  if ( ! is_string( $html ) || strpos( $html, 'fa-' ) === false ) {
    return $html;
  }
  return preg_replace_callback(
    '/<i\s+class="([^"]*)"[^>]*>\s*<\/i>/i',
    function ( $match ) {
      $classes = preg_split( '/\s+/', trim( $match[1] ) );
      $style   = 'solid';
      $name    = '';
      foreach ( $classes as $class ) {
        if ( in_array( $class, array( 'fa-brands', 'fab' ), true ) ) {
          $style = 'brands';
        } elseif ( in_array( $class, array( 'fa-regular', 'far' ), true ) ) {
          $style = 'regular';
        } elseif ( in_array( $class, array( 'fa-solid', 'fas' ), true ) ) {
          $style = 'solid';
        } elseif ( strpos( $class, 'fa-' ) === 0 ) {
          $name = substr( $class, 3 );
        }
      }
      $svg = $name ? webokids_icon( $name, $style ) : '';
      return $svg ? $svg : $match[0];
    },
    $html
  );
}

// Formularios de Contact Form 7 que usan íconos de Font Awesome.
add_filter( 'wpcf7_form_elements', 'webokids_replace_fa_icons' );
